{
  "title": "tBregs and Tumor Growth",
  "perWatchSecond": 1,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "tBregs Drive Maximum Tumor Size",
      "goal": "Show that a high tBreg population forces the tumor to reach its carrying capacity despite active NK cells.",
      "control": {
        "parameter": "m_T",
        "label": "Tumor-induced tBreg growth rate",
        "lowEnd": "0.5× original",
        "highEnd": "2× original"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "Double the tumor-induced tBreg growth rate",
        "parameter": "m_T",
        "value": 1e-14
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "higher",
        "by": 50
      },
      "effect": "With m_T doubled, the tumor peak increases from about 99 to over 149, showing tBregs can drive the tumor to its maximum size.",
      "prediction": {
        "prompt": "Will doubling m_T raise the tumor peak?",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Headline Result",
        "quote": "a sufficiently large number of tBregs can cause the breast tumour to reach its carrying capacity, regardless of the rate of NK-induced breast cancer cell death."
      },
      "carryForward": "Keep m_T at the doubled value for subsequent levels."
    },
    {
      "kind": "background",
      "finding": 2,
      "title": "NK Cells Control Tumor Without tBregs",
      "goal": "Demonstrate that without tBregs, tumor size depends on NK killing rate.",
      "control": {
        "parameter": "c",
        "label": "NK-induced tumor death rate",
        "lowEnd": "0.5× original",
        "highEnd": "2× original"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "Halve the NK killing rate while tBregs are absent",
        "parameter": "b0",
        "value": 0
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 30
      },
      "effect": "With tBregs removed, halving c reduces the tumor peak from ~99 to ~69, showing NK activity limits tumor size.",
      "prediction": {
        "prompt": "Will removing tBregs and halving c lower the tumor peak?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Result 2",
        "quote": "when tBregs do not exist in the body, the only way for the breast tumour to reach its carrying capacity is for the rate of NK-induced breast cancer cell death to be tending to 0"
      },
      "carryForward": "Keep b0 at 0 for the next level."
    },
    {
      "kind": "idea",
      "finding": 4,
      "title": "NK Killing Rate Thresholds",
      "goal": "Identify the critical NK killing rates that shift tumor outcomes.",
      "control": {
        "parameter": "c",
        "label": "NK-induced tumor death rate",
        "lowEnd": "0.5× original",
        "highEnd": "2× original"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "Double the NK killing rate",
        "parameter": "c",
        "value": 4e-10
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 40
      },
      "effect": "Doubling c drops the tumor peak from ~99 to ~59, illustrating a bifurcation threshold where stronger NK killing prevents maximal tumor growth.",
      "prediction": {
        "prompt": "Will doubling c lower the tumor peak?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Result 4",
        "quote": "System [reducedModel] experiences a transcritical bifurcation at the equilibrium point E1 ≡ E2 as the parameter c varies through c1."
      },
      "carryForward": "Use the doubled c value in subsequent explorations."
    },
    {
      "kind": "method",
      "finding": 5,
      "title": "tBreg Death Outpaces Activation",
      "goal": "Show that a high tBreg death rate eliminates tBregs and mimics their absence.",
      "control": {
        "parameter": "thetaB",
        "label": "tBreg death rate",
        "lowEnd": "0.5× original",
        "highEnd": "2× original"
      },
      "watch": "b",
      "whatIf": {
        "prompt": "Double the tBreg death rate",
        "parameter": "thetaB",
        "value": 0.8
      },
      "difference": {
        "compartment": "b",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 450000
      },
      "effect": "Doubling thetaB reduces the tBreg peak from 500,000 to near zero, causing the tumor to behave as if tBregs were absent.",
      "prediction": {
        "prompt": "Will doubling thetaB lower the tBreg peak?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Result 5",
        "quote": "when θB/mT > 1/b, our model has no closed orbits, meaning that breast cancer will either be cleared by NK cells or stabilise around a constant number."
      },
      "carryForward": "Maintain the doubled thetaB for the final level."
    },
    {
      "kind": "evaluation",
      "finding": 6,
      "title": "Cancer Dormancy Emerges",
      "goal": "Reveal a low‑level tumor equilibrium (dormancy) when immune pressures balance.",
      "control": {
        "parameter": "gamma",
        "label": "Treg‑induced NK cell death rate",
        "lowEnd": "0.5× original",
        "highEnd": "2× original"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "Halve the Treg‑induced NK death rate",
        "parameter": "gamma",
        "value": 5e-11
      },
      "difference": {
        "compartment": "t",
        "summary": "mean",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 20
      },
      "effect": "Halving gamma lowers the average tumor size over 70 days from ~70 to ~50, indicating a stable low‑level dormancy state.",
      "prediction": {
        "prompt": "Will halving gamma reduce the average tumor size?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Result 6",
        "quote": "This phenomenon is known as cancer dormancy and it happens to 20–45% of breast cancer patients"
      },
      "carryForward": "Use the halved gamma setting for any further analysis."
    }
  ],
  "limits": [
    "Each level must run no longer than 20 seconds at 4× speed.",
    "The control slider must cover at least a halving and a doubling of the chosen rate.",
    "The What‑if change must produce a visible difference of at least 10% of the chart height.",
    "Predictions must be binary (higher/lower) and testable against the model output."
  ]
}
